"""Persist final whole-pose production briefs alongside the selected sources."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];ART=ROOT/'art/goku/combat'
data=json.loads((ART/'prompts-standing.json').read_text(encoding='utf-8'))
common=data['prompts']['stand_light'].split('Attack STANDING')[0]
briefs={
 'down_getup':'Sheet KNOCKDOWN, GETUP AND KO, full coherent drawings. After standing calibration:2falls onto one bracing hand and hip, knees bending;3rolls onto side with both legs and boots complete;4settled down lying sideways on ground, head/face visible and legs naturally bent;5same KO lying pose settles subtly with relaxed hand/hair;6pushes from ground with palm and hip, begins rising;7kneels on one knee and plants other foot;8rises through balanced half squat using legs;9nearly canonical upright combat guard. Same anatomical scale; lying pose may be wide but MUST fit fully with generous margin, never clipped. No folded/vanishing calves, extra arms, gore or effects. No weapon. All ground contact at consistent local floor. KO looks defeated, not asleep smiling.',
 'throw_attacker':'Sheet MARTIAL HIP THROW attacker Goku ALONE, no second character. After standing calibration:2reaches forward to grab at opponent shoulder height with natural elbow/hand, feet braced;3gripping hands forward, knees bend and shoulders engage;4pulls captured opponent inward toward hip, hands and forearms draw back;5pivots hips/shoulders and lowers center of gravity, arms lifting;6strong hip/shoulder throw follow-through with arms up-and-forward, weight transferred through grounded supporting leg;7arms extend towardRIGHT/downward as imagined target is released;8hands retract and legs regain balance;9returns to confident fighting guard. Hands can open to grip, do not draw a weapon or an actual opponent. Real body rotation and knee work, not a fist shifted. Full boots/hair/arms inside every cell. Keep face recognizable even during turn.',
 'grabbed_victim':'Sheet GOKU BEING GRABBED AND THROWN, Goku ALONE, no attacker drawn. After standing calibration:2upper arms constrained close, torso pulled forward, startled strained face;3resists pull with bent knees and braced feet, arms caught;4body lifted slightly, bent knees leave floor, torso tilted over imagined hip;5carried/tilted airborne reaction, shoulders recoiling and coherent bent legs;6released into a sideways downward tumble, arms reflexively open;7unfolds legs while falling, face strained;8stumbles onto ground with one knee and hand bracing;9recovers half crouch guard. Cells2-3grounded,4-7airborne,8-9grounded. Same limbs/boots/hair/head size throughout. Full complete natural anatomy, no rotated cutouts, stretching, missing hands or fused legs. No gore/effects/weapons/other people.'
}
(ART/'prompts-final.json').write_text(json.dumps({'tool':'built-in image_gen','reference':data['reference'],'productionBriefs':{k:common+v for k,v in briefs.items()}},indent=2)+'\n',encoding='utf-8')
print('Final secondary production briefs recorded.')
